import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

cpp_decl = r"""
#include <torch/extension.h>
torch::Tensor conv_transpose3d_cute(torch::Tensor x, torch::Tensor weight, int64_t kernel_size);
"""

cuda_src = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <c10/cuda/CUDAStream.h>
#include <cute/tensor.hpp>
using namespace cute;
#define TILE_H 16
#define TILE_W 16
#define COUT_TILE 24
#define CIN_CHUNK 32
#define MAX_SUPPORTED_COUT_TILES 8
template <int NUM_COUT_TILES>
__global__ void convtranspose3d_kernel(
    const float* __restrict__ input,
    const float* __restrict__ weight,
    float* __restrict__ output,
    int N, int Cin, int D, int H, int W,
    int Cout, int Kd, int Kh, int Kw,
    int D_out, int H_out, int W_out)
{
    const int HALO_H = TILE_H + 2;
    const int HALO_W = TILE_W + 2;
    int ow0 = blockIdx.x * TILE_W;
    int oh0 = blockIdx.y * TILE_H;
    int n  = blockIdx.z / D_out;
    int od = blockIdx.z % D_out;
    int tx = threadIdx.x;
    int ty = threadIdx.y;
    int tid = ty * TILE_W + tx;
    int nthreads = TILE_W * TILE_H;
    int oh = oh0 + ty;
    int ow = ow0 + tx;
    extern __shared__ float smem[];
    // CuTe tensor view over shared memory tile for one chunk of input
    // channels: [CIN_CHUNK, HALO_H, HALO_W]. Input channels are processed in
    // chunks of CIN_CHUNK so that the dynamic shared memory footprint stays
    // within hardware limits regardless of Cin/Cout. This tile is loaded
    // once per (kd, cin_start) and reused across ALL output-channel tiles,
    // avoiding redundant reloads of the same input activations that the
    // previous implementation performed once per output-channel tile.
    auto sTile = make_tensor(make_smem_ptr(smem),
        make_shape(CIN_CHUNK, HALO_H, HALO_W),
        make_stride(HALO_H * HALO_W, HALO_W, 1));
    // Shared-memory staging of the weight slice for the current kd and the
    // current chunk of input channels, reused by all threads in the block.
    int input_tile_elems = CIN_CHUNK * HALO_H * HALO_W;
    auto sWeight = make_tensor(make_smem_ptr(smem + input_tile_elems),
        make_shape(CIN_CHUNK, COUT_TILE, Kh, Kw),
        make_stride(COUT_TILE * Kh * Kw, Kh * Kw, Kw, 1));
    // CuTe tensor views over global memory
    auto gInput = make_tensor(make_gmem_ptr(input),
        make_shape(N, Cin, D, H, W),
        make_stride(Cin * D * H * W, D * H * W, H * W, W, 1));
    auto gWeight = make_tensor(make_gmem_ptr(weight),
        make_shape(Cin, Cout, Kd, Kh, Kw),
        make_stride(Cout * Kd * Kh * Kw, Kd * Kh * Kw, Kh * Kw, Kw, 1));
    auto gOutput = make_tensor(make_gmem_ptr(output),
        make_shape(N, Cout, D_out, H_out, W_out),
        make_stride(Cout * D_out * H_out * W_out, D_out * H_out * W_out, H_out * W_out, W_out, 1));
    int total_halo = HALO_H * HALO_W;
    // Accumulator register tile is sized exactly to the number of output-channel
    // tiles required for this Cout (NUM_COUT_TILES, a compile-time template
    // parameter chosen by the host launcher via a small dispatch switch).
    // Previously the accumulator was always sized to a fixed MAX_COUT_TILES=16
    // regardless of the actual number of output-channel tiles needed, forcing
    // every thread to reserve registers for up to 16*COUT_TILE=384 floats even
    // when only a couple of tiles were used (e.g. Cout=48 -> 2 tiles). That
    // massive over-provisioning caused register spilling to local memory and
    // collapsed occupancy. Templating on the exact tile count keeps the same
    // (kd, cin_start)-outermost reuse pattern for the input halo tile while
    // using only as many accumulator registers as are actually needed.
    float acc[NUM_COUT_TILES][COUT_TILE];
    #pragma unroll
    for (int t = 0; t < NUM_COUT_TILES; ++t) {
        #pragma unroll
        for (int co = 0; co < COUT_TILE; ++co) {
            acc[t][co] = 0.f;
        }
    }
    for (int kd = 0; kd < Kd; ++kd) {
        int id = od - kd;
        bool valid_id = (id >= 0 && id < D);
        if (valid_id) {
            for (int cin_start = 0; cin_start < Cin; cin_start += CIN_CHUNK) {
                int chunk_size = (Cin - cin_start < CIN_CHUNK) ? (Cin - cin_start) : CIN_CHUNK;
                for (int ci_local = 0; ci_local < chunk_size; ++ci_local) {
                    int ci = cin_start + ci_local;
                    for (int idx = tid; idx < total_halo; idx += nthreads) {
                        int lh = idx / HALO_W;
                        int lw = idx % HALO_W;
                        int ih = oh0 - 2 + lh;
                        int iw = ow0 - 2 + lw;
                        float v = 0.f;
                        if (ih >= 0 && ih < H && iw >= 0 && iw < W) {
                            v = gInput(n, ci, id, ih, iw);
                        }
                        sTile(ci_local, lh, lw) = v;
                    }
                }
                __syncthreads();
                for (int cout0 = 0; cout0 < Cout; cout0 += COUT_TILE) {
                    int cout_tile = (Cout - cout0 < COUT_TILE) ? (Cout - cout0) : COUT_TILE;
                    int t = cout0 / COUT_TILE;
                    int total_weight_chunk = chunk_size * cout_tile * Kh * Kw;
                    for (int idx = tid; idx < total_weight_chunk; idx += nthreads) {
                        int ci_local = idx / (cout_tile * Kh * Kw);
                        int rem = idx % (cout_tile * Kh * Kw);
                        int co = rem / (Kh * Kw);
                        int rem2 = rem % (Kh * Kw);
                        int kh = rem2 / Kw;
                        int kw = rem2 % Kw;
                        int ci = cin_start + ci_local;
                        sWeight(ci_local, co, kh, kw) = gWeight(ci, cout0 + co, kd, kh, kw);
                    }
                    __syncthreads();
                    if (oh < H_out && ow < W_out) {
                        for (int kh = 0; kh < Kh; ++kh) {
                            int lh = ty - kh + 2;
                            for (int kw = 0; kw < Kw; ++kw) {
                                int lw = tx - kw + 2;
                                for (int ci_local = 0; ci_local < chunk_size; ++ci_local) {
                                    float v = sTile(ci_local, lh, lw);
                                    #pragma unroll
                                    for (int co = 0; co < COUT_TILE; ++co) {
                                        if (co < cout_tile) {
                                            acc[t][co] += v * sWeight(ci_local, co, kh, kw);
                                        }
                                    }
                                }
                            }
                        }
                    }
                    __syncthreads();
                }
            }
        }
    }
    if (oh < H_out && ow < W_out) {
        for (int cout0 = 0; cout0 < Cout; cout0 += COUT_TILE) {
            int cout_tile = (Cout - cout0 < COUT_TILE) ? (Cout - cout0) : COUT_TILE;
            int t = cout0 / COUT_TILE;
            #pragma unroll
            for (int co = 0; co < COUT_TILE; ++co) {
                if (co < cout_tile) {
                    gOutput(n, cout0 + co, od, oh, ow) = acc[t][co];
                }
            }
        }
    }
}
template <int NUM_COUT_TILES>
static void launch_convtranspose3d_kernel(
    const float* x_ptr, const float* w_ptr, float* out_ptr,
    int N, int Cin, int D, int H, int W,
    int Cout, int K, int D_out, int H_out, int W_out,
    dim3 grid, dim3 block, size_t shared_bytes, cudaStream_t stream)
{
    int dev = 0;
    cudaGetDevice(&dev);
    int max_optin = 0;
    cudaDeviceGetAttribute(&max_optin, cudaDevAttrMaxSharedMemoryPerBlockOptin, dev);
    TORCH_CHECK((size_t)max_optin >= shared_bytes,
                "Requested shared memory (", shared_bytes,
                " bytes) exceeds device max opt-in (", max_optin,
                " bytes). Reduce CIN_CHUNK/COUT_TILE.");
    cudaError_t attr_err = cudaFuncSetAttribute(convtranspose3d_kernel<NUM_COUT_TILES>,
                          cudaFuncAttributeMaxDynamicSharedMemorySize,
                          (int)shared_bytes);
    TORCH_CHECK(attr_err == cudaSuccess,
                "cudaFuncSetAttribute failed: ", cudaGetErrorString(attr_err),
                " (requested ", shared_bytes, " bytes)");
    convtranspose3d_kernel<NUM_COUT_TILES><<<grid, block, shared_bytes, stream>>>(
        x_ptr, w_ptr, out_ptr,
        N, Cin, D, H, W,
        Cout, K, K, K,
        D_out, H_out, W_out);
}
torch::Tensor conv_transpose3d_cute(torch::Tensor x, torch::Tensor weight, int64_t kernel_size) {
    TORCH_CHECK(x.is_cuda() && weight.is_cuda(), "Inputs must be CUDA tensors");
    TORCH_CHECK(x.dim() == 5, "x must be 5D (N,C,D,H,W)");
    TORCH_CHECK(weight.dim() == 5, "weight must be 5D (Cin,Cout,K,K,K)");
    TORCH_CHECK(x.scalar_type() == at::kFloat && weight.scalar_type() == at::kFloat,
                "Expect float32 tensors");
    auto x_c = x.contiguous();
    auto w_c = weight.contiguous();
    int N   = (int)x_c.size(0);
    int Cin = (int)x_c.size(1);
    int D   = (int)x_c.size(2);
    int H   = (int)x_c.size(3);
    int W   = (int)x_c.size(4);
    int Cout = (int)w_c.size(1);
    int K    = (int)kernel_size;
    TORCH_CHECK(w_c.size(0) == Cin, "weight in_channels mismatch");
    // Output channels are processed in COUT_TILE-sized register tiles inside the kernel.
    int num_cout_tiles = (Cout + COUT_TILE - 1) / COUT_TILE;
    TORCH_CHECK(num_cout_tiles >= 1 && num_cout_tiles <= MAX_SUPPORTED_COUT_TILES,
                "Cout too large for the number of output-channel accumulator tiles supported by this kernel");
    // stride=1, padding=0, output_padding=0 (default ConvTranspose3d config used in Model)
    int D_out = D + K - 1;
    int H_out = H + K - 1;
    int W_out = W + K - 1;
    auto out = torch::zeros({N, Cout, D_out, H_out, W_out}, x_c.options());
    dim3 block(TILE_W, TILE_H, 1);
    dim3 grid((W_out + TILE_W - 1) / TILE_W,
              (H_out + TILE_H - 1) / TILE_H,
              N * D_out);
    // Shared memory now only needs to hold one CIN_CHUNK-sized slice of the
    // input halo and weight tensors at a time, keeping the footprint well
    // within hardware per-block shared memory limits regardless of Cin/Cout.
    size_t shared_bytes = (size_t)CIN_CHUNK * (TILE_H + 2) * (TILE_W + 2) * sizeof(float)
                         + (size_t)CIN_CHUNK * COUT_TILE * K * K * sizeof(float);
    cudaStream_t stream = c10::cuda::getCurrentCUDAStream().stream();
    // Dispatch to a template instantiation whose accumulator register tile is
    // sized exactly to num_cout_tiles, avoiding the register-spilling
    // over-provisioning of a fixed, worst-case-sized accumulator array.
    switch (num_cout_tiles) {
        case 1: launch_convtranspose3d_kernel<1>(x_c.data_ptr<float>(), w_c.data_ptr<float>(), out.data_ptr<float>(), N, Cin, D, H, W, Cout, K, D_out, H_out, W_out, grid, block, shared_bytes, stream); break;
        case 2: launch_convtranspose3d_kernel<2>(x_c.data_ptr<float>(), w_c.data_ptr<float>(), out.data_ptr<float>(), N, Cin, D, H, W, Cout, K, D_out, H_out, W_out, grid, block, shared_bytes, stream); break;
        case 3: launch_convtranspose3d_kernel<3>(x_c.data_ptr<float>(), w_c.data_ptr<float>(), out.data_ptr<float>(), N, Cin, D, H, W, Cout, K, D_out, H_out, W_out, grid, block, shared_bytes, stream); break;
        case 4: launch_convtranspose3d_kernel<4>(x_c.data_ptr<float>(), w_c.data_ptr<float>(), out.data_ptr<float>(), N, Cin, D, H, W, Cout, K, D_out, H_out, W_out, grid, block, shared_bytes, stream); break;
        case 5: launch_convtranspose3d_kernel<5>(x_c.data_ptr<float>(), w_c.data_ptr<float>(), out.data_ptr<float>(), N, Cin, D, H, W, Cout, K, D_out, H_out, W_out, grid, block, shared_bytes, stream); break;
        case 6: launch_convtranspose3d_kernel<6>(x_c.data_ptr<float>(), w_c.data_ptr<float>(), out.data_ptr<float>(), N, Cin, D, H, W, Cout, K, D_out, H_out, W_out, grid, block, shared_bytes, stream); break;
        case 7: launch_convtranspose3d_kernel<7>(x_c.data_ptr<float>(), w_c.data_ptr<float>(), out.data_ptr<float>(), N, Cin, D, H, W, Cout, K, D_out, H_out, W_out, grid, block, shared_bytes, stream); break;
        case 8: launch_convtranspose3d_kernel<8>(x_c.data_ptr<float>(), w_c.data_ptr<float>(), out.data_ptr<float>(), N, Cin, D, H, W, Cout, K, D_out, H_out, W_out, grid, block, shared_bytes, stream); break;
        default: TORCH_CHECK(false, "Unsupported num_cout_tiles");
    }
    cudaError_t launch_err = cudaGetLastError();
    TORCH_CHECK(launch_err == cudaSuccess, "conv_transpose3d_cute launch failed: ",
                cudaGetErrorString(launch_err));
    return out;
}
"""

cute_ext = load_inline(
    name="cute_convtranspose3d_ext",
    cpp_sources=cpp_decl,
    cuda_sources=cuda_src,
    functions=["conv_transpose3d_cute"],
    extra_cflags=["-O3", "-I/workspace/cutegen_test/cutegen/cutlass/include"],
    extra_cuda_cflags=["-O3", "-I/workspace/cutegen_test/cutegen/cutlass/include"],
    verbose=False,
)


class ModelNew(nn.Module):
    """
    Performs a transposed 3D convolution (stride=1, padding=0, output_padding=0,
    groups=1, bias=False) using a custom CuTe-based CUDA kernel.
    """
    def __init__(self, in_channels: int, out_channels: int, kernel_size: int,
                 stride: int = 1, padding: int = 0, output_padding: int = 0,
                 groups: int = 1, bias: bool = False) -> None:
        super(ModelNew, self).__init__()
        assert stride == 1 and padding == 0 and output_padding == 0 and groups == 1 and bias == False, \
            "Custom kernel only supports stride=1, padding=0, output_padding=0, groups=1, bias=False"
        # Reuse nn.ConvTranspose3d only to get correctly-initialized weight parameter
        self.conv_transpose3d = nn.ConvTranspose3d(
            in_channels, out_channels, kernel_size=(kernel_size, kernel_size, kernel_size),
            stride=stride, padding=padding, output_padding=output_padding,
            groups=groups, bias=bias
        )
        self.kernel_size = kernel_size
        self._ext = cute_ext

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        weight = self.conv_transpose3d.weight
        return self._ext.conv_transpose3d_cute(x.contiguous().float(), weight, self.kernel_size)

