import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

cpp_decl = r"""
#include <torch/extension.h>
torch::Tensor conv_transpose3d_cute(torch::Tensor x, torch::Tensor weight, int64_t kernel_size);
